Exactoo. Ahora el programa completo:

```c
#include <stdio.h>

float leerEnRango(float min, float max) {
    float valor;
    do {
        printf("Ingrese un valor entre %.2f y %.2f: ", min, max);
        scanf("%f", &valor);
        if (valor < min || valor > max) {
            printf("Valor fuera de rango. Intente de nuevo.\n");
        }
    } while (valor < min || valor > max);
    return valor;
}

int main() {
    int n, i;
    float min, max, valor;

    printf("Cuantos valores desea leer? ");
    scanf("%d", &n);

    printf("Minimo del rango: ");
    scanf("%f", &min);
    printf("Maximo del rango: ");
    scanf("%f", &max);

    for (i = 0; i < n; i++) {
        printf("\nValor %d:\n", i + 1);
        valor = leerEnRango(min, max);
        printf("Valor aceptado: %.2f\n", valor);
    }

    return 0;
}
```

¿Qué pasaría si el usuario ingresa min mayor que max? ¿La función actual detecta ese error?
